        let t88 = (-x[4]).mul_add(t15, t87);
        let t89 = t88 * T::from_i64(2);
        let t90 = x[0].mul_add(s0, t89);
        let t91 = (-x[5]).mul_add(t15, t51);
        let t92 = (-x[7]).mul_add(t23, t91);
        let t93 = t92 * T::from_i64(2);
        let t94 = x[1].mul_add(s0, t93);
        let t95 = x[6].mul_add(t15, t54);
        let t96 = x[8].mul_add(t39, t95);
        let t98 = (-t96).mul_add(T::from_i64(2), t52);
