        let t102 = x[3].mul_add(s0, t101);
        let t103 = t61 * T::from_i64(2);
        let t104 = x[4].mul_add(s0, t103);
        let t105 = t63 * T::from_i64(2);
        let t106 = x[5].mul_add(s0, t105);
        let t107 = t65 * T::from_i64(2);
        let t108 = x[6].mul_add(s0, t107);
        let t110 = (-t66).mul_add(T::from_i64(2), t67);
        let t112 = (-t68).mul_add(T::from_i64(2), t69);
        let t114 = (-t70).mul_add(T::from_i64(2), t71);
        let t115 = (-x[8]).mul_add(t42, t72);
        let t116 = (-x[4]).mul_add(t43, t115);
