impl<T: gx::Real> Quadvector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t1 = -t0;
        t1
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (9 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Quadvector<(), T> {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t1 = x[4] * t0;
        let t2 = x[4] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = x[4] * t4;
        let t10 = -t5;
        let t11 = -t6;
        let t12 = -t7;
        let t13 = -t8;
        let t14 = -t9;
        Quadvector::from_coeffs([t10, t11, t12, t13, t14])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[4] * x[4];
        let p1 = -p0;
        let s0 = (p1).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Quadvector::from_coeffs([t0, t1, t2, t3, t4]))
    }

}

impl<T: gx::Coef> gx::NewtonStep for Quadvector<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t2 = t0.mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t3 = x[0] * t2;
        let t4 = x[1] * t2;
        let t5 = x[2] * t2;
        let t6 = x[3] * t2;
        let t7 = x[4] * t2;
        let t8 = t3 * T::from_ratio(3, 2);
        let t9 = t4 * T::from_ratio(3, 2);
        let t10 = t5 * T::from_ratio(3, 2);
        let t11 = t6 * T::from_ratio(3, 2);
        let t12 = t7 * T::from_ratio(3, 2);
        Quadvector::from_coeffs([t8, t9, t10, t11, t12])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

