impl<T: gx::Real> Motor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[5] * x[5];
        let t3 = x[7] * x[7];
        let t5 = x[9] * x[9];
        let t7 = x[15] * x[15];
        let t8 = x[0].mul_add(x[0], t1);
        let t9 = x[6].mul_add(x[6], t3);
        let t10 = t8 + t9;
        let t11 = x[8].mul_add(x[8], t5);
        let t12 = x[10].mul_add(x[10], t7);
        let t13 = t11 + t12;
        let t14 = t10 - t13;
        t14
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, by Shirokov's method in `Motor` (no closed form
    /// for `Motor` here): the inverse as a polynomial of degree 3 whose coefficients come
    /// from the scalar parts of powers (the FaddeevâLeVerrier recursion on left multiplication,
    /// 3 products in `Motor`), on the part of `x` free of the null direction(s), then a finite series for the
    /// nilpotent rest (1 term(s)), then 1 NewtonâSchulz step(s) (docs/design.md, ADR-037). `x` is scaled to its largest
    /// coefficient first. Not finite where `x` has no inverse.
    #[inline]
    pub fn inverse(self) -> Motor<(), T>
    where
        T: gx::Real,
    {
        T::vectorize(#[inline(always)] move || {
        let mut size = T::zero();
        for c in self.c {
            size = size.max(c.abs());
        }
        let scale = size.recip();
        let mut x = Motor::<(), T>::zero();
        x.c[0] = self.c[0] * scale;
        x.c[1] = self.c[1] * scale;
        x.c[2] = self.c[2] * scale;
        x.c[3] = self.c[3] * scale;
        x.c[4] = self.c[4] * scale;
        x.c[5] = self.c[5] * scale;
        x.c[6] = self.c[6] * scale;
        x.c[7] = self.c[7] * scale;
        x.c[8] = self.c[8] * scale;
        x.c[9] = self.c[9] * scale;
        x.c[10] = self.c[10] * scale;
        x.c[11] = self.c[11] * scale;
        x.c[12] = self.c[12] * scale;
        x.c[13] = self.c[13] * scale;
        x.c[14] = self.c[14] * scale;
        x.c[15] = self.c[15] * scale;
        // The body `a` (no null direction) and the nilpotent rest `n = x â a`.
        let mut a = x;
        a.c[1] = T::zero(); a.c[2] = T::zero(); a.c[3] = T::zero(); a.c[4] = T::zero(); a.c[11] = T::zero(); a.c[12] = T::zero(); a.c[13] = T::zero(); a.c[14] = T::zero();
        let n = x - a;
        // Uâ = a, Câ = (N/k) â¨Uââ©â, Uâââ = a (Uâ â Câ); then aâ»Â¹ = (U_{Nâ1} â C_{Nâ1}) / C_N.
        let mut prev = a;
        let c = a.c[0] * T::from_i64(4);
        prev.c[0] = prev.c[0] - c;
        for k in 2..4i64 {
            let u = a * prev;
            let c = u.c[0] * T::from_ratio(4, k);
            prev = u;
            prev.c[0] = prev.c[0] - c;
        }
        let det = (a * prev).c[0];
        let mut y = prev.gp(det.recip());
        // xâ»Â¹ = Î£â (âaâ»Â¹ n)áµ aâ»Â¹, k = 0..=1: (aâ»Â¹ n)^2 = 0, every term holding a null
        // direction twice.
        let m = -(y * n);
        let mut term = y;
        for _ in 0..1 {
            term = m * term;
            y = y + term;
        }
        // NewtonâSchulz, y â y (2 â x y), squares the residual: the recursion loses digits as
        // its degree grows (to 10â»â´ at degree 32), and the step(s) restore them.
        for _ in 0..1 {
            let mut t = -(x * y);
            t.c[0] = t.c[0] + T::from_i64(2);
            y = y * t;
        }
        y.gp(scale)
        })
    }

}

impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Motor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p0 = x[15] * x[15];
        let p1 = -p0;
        let [h0, h1] = gx::study::log_coeffs_q(x[0], p1);
        let t0 = x[15] * h1;
        let t1 = x[11] * h1;
        let t2 = x[12] * h1;
        let t3 = x[13] * h1;
        let t4 = x[14] * h1;
        let t7 = x[9] * t3;
        let t8 = x[10] * t2;
        let t11 = x[8] * t3;
        let t12 = x[10] * t1;
        let t15 = x[8] * t2;
        let t16 = x[9] * t1;
        let t18 = x[5] * t1;
        let t20 = x[7] * t3;
        let t21 = x[5] * h0;
        let t23 = x[6] * h0;
        let t25 = x[7] * h0;
        let t28 = x[8] * h0;
        let t30 = x[9] * h0;
        let t32 = x[10] * h0;
        let t33 = x[1].mul_add(h0, t7);
        let t34 = x[5].mul_add(t4, t8);
        let t35 = t33 - t34;
        let t36 = x[2].mul_add(h0, t12);
        let t37 = x[6].mul_add(t4, t11);
        let t38 = t36 - t37;
        let t39 = x[3].mul_add(h0, t15);
        let t40 = x[7].mul_add(t4, t16);
        let t41 = t39 - t40;
        let t42 = x[4].mul_add(h0, t18);
        let t43 = x[6].mul_add(t2, t20);
        let t44 = t42 + t43;
        let t45 = (-x[8]).mul_add(t0, t21);
        let t46 = (-x[9]).mul_add(t0, t23);
        let t47 = (-x[10]).mul_add(t0, t25);
        let t48 = x[5].mul_add(t0, t28);
        let t49 = x[6].mul_add(t0, t30);
        let t50 = x[7].mul_add(t0, t32);
        Bivector::from_coeffs([t35, t38, t41, t44, t45, t46, t47, t48, t49, t50])
        })
    }
}

